// @name JSX: Kitchen sink
// @background #0b1020
// @refresh 0.05
// Most of what the JSX layer does, on one 480x480 touch screen, in five pages:
// - Controls: switches, a slider you drag, a stepper (hold + for ten,
//   double-tap the number to zero it) and the accent color the UI follows.
// - Paint: tap or drag on the canvas to draw, pick a color and a brush, Undo,
//   hold Clear. A canvas (frameos.canvas): a stroke is drawn once, as lines
//   between the points the finger passes, and a frame repaints only those.
// - Lights: the Lights Out puzzle, every cell memo()'d.
// - Motion: balls bouncing on the clock, a spinner and a wave. The scene runs
//   at 0.05 s, so it animates; the other pages ask for one render a second
//   (frameos.setNextSleep), on the second, for the clock in the header.
// - Touch: every gesture and move the glass makes, where it landed, how many
//   of each, and the hover:, active: and group-hover: classes.
// Everything lives in frameos.remember, so it outlasts the interpreter, and
// every change bumps a revision: the pages are memo()'d on it, so the clock's
// render each second takes the page back whole and lays out the header alone.

const ACCENTS = ['sky', 'violet', 'emerald', 'rose', 'amber']
const INKS = ['#0f172a', '#ef4444', '#f59e0b', '#22c55e', '#3b82f6']
const BRUSHES = [4, 9, 16]
const TABS = [
  ['controls', 'Controls', 'M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6'],
  ['paint', 'Paint', 'M18.4 2.6a2 2 0 0 1 3 3L12 15l-4 1 1-4zM7 17c-2 0-3 1.5-3 3s-1 1.5-2 2c3 0 7 0 7-3a2 2 0 0 0-2-2z'],
  ['lights', 'Lights', 'M3 3h7v7H3zM14 3h7v7h-7zM14 14h7v7h-7zM3 14h7v7H3z'],
  ['motion', 'Motion', 'M22 12h-4l-3 9L9 3l-3 9H2'],
  ['touch', 'Touch', 'M12 2v4M12 18v4M2 12h4M18 12h4M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z'],
]
const EVENT_COLORS = {
  tap: '#38bdf8', doubleTap: '#a78bfa', longPress: '#fbbf24', pointerDown: '#f8fafc', pointerUp: '#64748b',
  pointerMove: '#34d399',
}
// The pages' drawing areas, in pixels: the UI less the page's padding, and
// what the header (48), the tab bar (64) and each page's own rows leave, with
// the brightness slider (less its card's padding) and the Lights board. Set by
// fit() at every render, for the handlers that run before the next; these are
// a 480x480 screen's.
let pageW = 448, sliderW = 416, boardW = 284, cellW = 52
let paintH = 276, motionH = 292, padH = 208

const DEFAULTS = {
  tab: 'controls', accent: 'sky',
  toggles: [true, false, true], level: 60, count: 3,
  strokes: [], based: 0, ink: 1, brush: 1,
  board: null, moves: 0,
  balls: null,
  events: [], counts: { tap: 0, doubleTap: 0, longPress: 0, pointerDown: 0, pointerUp: 0, pointerMove: 0 },
}
let S = null
const load = () => {
  if (S === null) S = Object.assign({}, DEFAULTS, frameos.recall('sink') ?? {})
  if (!S.board) newGame()
  if (!S.balls) S.balls = [newBall(120, 90, 0), newBall(300, 200, 1)]
}
const save = () => { S.rev = (S.rev ?? 0) + 1; frameos.remember('sink', S) }
const set = (patch) => { Object.assign(S, patch); save() }

// ---------------------------------------------------------------- pieces

const Icon = ({ d, className }) => (
  <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}
    strokeLinecap="round" strokeLinejoin="round"><path d={d} /></svg>
)

const Mark = () => (
  <svg className="w-6 h-7" viewBox="0 0 24 28">
    <path d="M1.5 14V1.5h21" fill="none" stroke="#ffffff" strokeWidth={3} strokeLinecap="round" />
    <path d="M22.5 16v10.5H12" fill="none" stroke="#ffffff" strokeWidth={3} strokeLinecap="round" />
    <rect x={4} y={18} width={6} height={6} rx={1.2} fill="#1c7c66" />
    <rect x={10} y={12} width={6} height={6} rx={1.2} fill="#8baa3a" />
    <rect x={16} y={6} width={6} height={6} rx={1.2} fill="#c8a247" />
  </svg>
)

const Tab = memo(({ id, label, d, active, accent, badge }) => (
  <div className={`flex-1 flex flex-col items-center justify-center gap-1 ${active ? `text-${accent}-300 bg-white/5` : 'text-slate-400 active:bg-white/10'}`}
    onClick={() => set({ tab: id })}>
    <Icon d={d} className="w-6 h-6" />
    <span className="text-xs font-semibold">{label}</span>
    {badge > 0 ? (
      <div className={`absolute top-1 right-3 flex items-center justify-center h-5 px-2 rounded-full bg-${accent}-500 text-white`}>
        <span className="text-xs font-bold">{`${badge > 99 ? '99+' : badge}`}</span>
      </div>
    ) : null}
  </div>
))

const Card = ({ className, children }) => (
  <div className={`rounded-2xl bg-white/5 border border-white/10 ${className ?? ''}`}>{children}</div>
)

// -------------------------------------------------------------- controls

const TOGGLES = [
  ['Lights', 'M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z'],
  ['Music', 'M9 18V5l12-2v13M6 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6zM18 13a3 3 0 1 0 0 6 3 3 0 0 0 0-6z'],
  ['Turbo', 'M13 2L3 14h9l-1 8 10-12h-9z'],
]

const Toggle = memo(({ i, on, accent }) => (
  <div className={`flex flex-col justify-between rounded-2xl p-3 ${on ? `bg-${accent}-500 text-white` : 'bg-white/5 border border-white/10 text-slate-300 active:bg-white/10'}`}
    onClick={() => { S.toggles[i] = !S.toggles[i]; save() }}>
    <div className="flex items-center justify-between">
      <Icon d={TOGGLES[i][1]} className="w-7 h-7" />
      <div className={`flex items-center w-11 h-6 rounded-full px-1 ${on ? 'justify-end bg-black/25' : 'justify-start bg-white/15'}`}>
        <div className="w-4 h-4 rounded-full bg-white" />
      </div>
    </div>
    <div className="flex flex-col">
      <span className="text-base font-semibold">{TOGGLES[i][0]}</span>
      <span className={`text-xs ${on ? 'text-white/80' : 'text-slate-500'}`}>{on ? 'On' : 'Off'}</span>
    </div>
  </div>
))

const Swatch = memo(({ color, chosen }) => (
  <div className={`w-9 h-9 rounded-full bg-${color}-500 ${chosen ? 'border-4 border-white' : 'active:border-2 active:border-white/60'}`}
    onClick={() => set({ accent: color })} />
))

const Controls = ({ accent }) => {
  const level = S.level
  // e.width: the slider's own (2026.10.22+); sliderW on an older frame.
  const setLevel = (e) => set({ level: Math.max(0, Math.min(100, Math.round((e.localX / (e.width ?? sliderW)) * 100))) })
  return (
    <div className="flex flex-col gap-3">
      <div className="grid grid-cols-3 gap-3 h-24">
        {S.toggles.map((on, i) => <Toggle i={i} on={on} accent={accent} />)}
      </div>
      <Card className="flex flex-col gap-2 p-4">
        <div className="flex items-center justify-between">
          <span className="text-sm text-slate-300 uppercase font-semibold">Brightness</span>
          <span className={`text-lg font-bold text-${accent}-300`}>{`${level}%`}</span>
        </div>
        <div className="h-9 rounded-full bg-white/10" onPointerDown={setLevel} onPointerMove={setLevel}>
          <div className={`h-9 rounded-full bg-gradient-to-r from-${accent}-700 to-${accent}-400 w-[${Math.round(Math.max(36, (level / 100) * sliderW))}px] flex items-center justify-end px-1`}>
            <div className="w-7 h-7 rounded-full bg-white" />
          </div>
        </div>
      </Card>
      <div className="flex gap-3 h-24">
        <Card className="flex-1 flex items-center justify-between px-3">
          <div className={`flex items-center justify-center w-11 h-11 rounded-full bg-white/10 active:bg-${accent}-700`}
            onClick={() => set({ count: S.count - 1 })}>
            <Icon d="M5 12h14" className="w-6 h-6" />
          </div>
          <div className="flex flex-col items-center" onDoubleClick={() => set({ count: 0 })}>
            <span className="text-4xl font-bold">{`${S.count}`}</span>
            <span className="text-xs text-slate-500">double-tap: 0</span>
          </div>
          <div className={`flex items-center justify-center w-11 h-11 rounded-full bg-${accent}-500 active:bg-${accent}-700`}
            onClick={() => set({ count: S.count + 1 })} onLongPress={() => set({ count: S.count + 10 })}>
            <Icon d="M12 5v14M5 12h14" className="w-6 h-6" />
          </div>
        </Card>
        <Card className="flex-1 flex flex-col justify-center gap-2 px-3">
          <span className="text-xs text-slate-400 uppercase font-semibold">Accent</span>
          <div className="flex justify-between">
            {ACCENTS.map((c) => <Swatch color={c} chosen={c === accent} />)}
          </div>
        </Card>
      </div>
    </div>
  )
}

// ----------------------------------------------------------------- paint

const Ink = memo(({ i, chosen }) => (
  <div className={`w-7 h-7 shrink-0 rounded-full bg-[${INKS[i]}] ${chosen ? 'border-4 border-white' : 'border-2 border-white/20'}`}
    onClick={() => set({ ink: i })} />
))

const Brush = memo(({ i, chosen }) => (
  <div className={`flex items-center justify-center w-7 h-7 shrink-0 rounded-lg ${chosen ? 'bg-white/20' : 'active:bg-white/10'}`}
    onClick={() => set({ brush: i })}>
    <div className={`rounded-full bg-white ${['w-1 h-1', 'w-2 h-2', 'w-4 h-4'][i]}`} />
  </div>
))

// Paint draws into a canvas (frameos.canvas): a stroke is lines from the
// last point to the next as the finger moves, drawn once, and a frame
// repaints only those. S.strokes is the record, [ink, brush, x0, y0, x1, y1,
// ...] each, for Undo and for a canvas made afresh (a new interpreter); it
// is drawn again only then, never per render. All but the last UNDO strokes
// are also in `base` (S.based of them), a second canvas Undo starts from, so
// an Undo copies it and draws a few strokes, not the whole record (seconds
// on an ESP32 once the record is full).
const PAPER = '#f1f5f9'
const INSET = 8
let canvasW = pageW - 2 * INSET, canvasH = paintH - 2 * INSET // the paper less its inset
const MAX_POINTS = 3000 // x, y pairs kept for a fresh canvas; the oldest strokes go past it
const UNDO = 12 // strokes Undo can take back
let canvas = null
let base = null
let drawing = null // the stroke the finger is drawing, while it is down

const strokeSvg = ([ink, brush, ...pts]) => pts.length === 2
  ? <circle cx={pts[0]} cy={pts[1]} r={BRUSHES[brush]} fill={INKS[ink]} />
  : <polyline points={pts.join(' ')} fill="none" stroke={INKS[ink]} strokeWidth={BRUSHES[brush] * 2}
      strokeLinecap="round" strokeLinejoin="round" />
// The canvas again: `base`, then the strokes it does not hold.
const redraw = () => {
  frameos.draw(canvas, <image href={base} x={0} y={0} width={canvasW} height={canvasH} preserveAspectRatio="none" />)
  for (const stroke of S.strokes.slice(S.based)) frameos.draw(canvas, strokeSvg(stroke))
}
// A finished stroke into the record; the oldest past UNDO go into `base`.
const keep = (stroke) => {
  S.strokes.push(stroke)
  while (S.strokes.length - S.based > UNDO) frameos.draw(base, strokeSvg(S.strokes[S.based++]))
  let points = S.strokes.reduce((n, s) => n + (s.length - 2) / 2, 0)
  while (points > MAX_POINTS && S.strokes.length > 1) {
    if (S.based === 0) frameos.draw(base, strokeSvg(S.strokes[S.based++]))
    points -= (S.strokes.shift().length - 2) / 2
    S.based--
  }
  save()
}
const paintAt = (e) => [Math.round(e.localX), Math.round(e.localY)]

const Paint = ({ accent }) => (
  <div className="flex flex-col gap-3">
    <div className={`w-[${pageW}px] h-[${paintH}px] rounded-2xl bg-[${PAPER}] p-[${INSET}px]`}>
      <img className={`w-[${canvasW}px] h-[${canvasH}px]`} src={canvas}
        onPointerDown={(e) => {
          const [x, y] = paintAt(e)
          drawing = [S.ink, S.brush, x, y]
          frameos.draw(canvas, strokeSvg(drawing))
        }}
        onPointerMove={(e) => {
          if (!drawing) return
          const [x, y] = paintAt(e)
          const [lx, ly] = drawing.slice(-2)
          if (Math.abs(x - lx) + Math.abs(y - ly) < 2) return
          frameos.draw(canvas, <line x1={lx} y1={ly} x2={x} y2={y} stroke={INKS[drawing[0]]}
            strokeWidth={BRUSHES[drawing[1]] * 2} strokeLinecap="round" />)
          drawing.push(x, y)
        }}
        onPointerUp={() => {
          if (!drawing) return
          keep(drawing)
          drawing = null
        }} />
      {S.strokes.length === 0 && !drawing ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-lg text-slate-400">Tap or drag to paint</span>
        </div>
      ) : null}
    </div>
    <div className="flex items-center justify-between h-12">
      <div className="flex items-center gap-[6px] shrink-0">
        {INKS.map((_, i) => <Ink i={i} chosen={i === S.ink} />)}
      </div>
      <div className="flex items-center gap-1 shrink-0">
        {BRUSHES.map((_, i) => <Brush i={i} chosen={i === S.brush} />)}
      </div>
      <div className="flex items-center gap-2 shrink-0">
        <div className="flex items-center justify-center h-9 px-3 rounded-lg bg-white/10 active:bg-white/20"
          onClick={() => { if (S.strokes.length > S.based) { S.strokes.pop(); redraw(); save() } }}>
          <span className={`text-sm font-semibold whitespace-nowrap ${S.strokes.length > S.based ? '' : 'text-white/40'}`}>Undo</span>
        </div>
        <div className={`flex flex-col items-center justify-center h-11 px-3 rounded-lg bg-${accent}-600 active:bg-${accent}-800`}
          onLongPress={() => { frameos.clear(canvas, PAPER); frameos.clear(base, PAPER); set({ strokes: [], based: 0 }) }}>
          <span className="text-sm font-semibold whitespace-nowrap">Clear</span>
          <span className="text-xs text-white/70 whitespace-nowrap">hold 1 s</span>
        </div>
      </div>
    </div>
  </div>
)

// ---------------------------------------------------------------- lights

const N = 5
const flip = (board, i) => {
  const x = i % N, y = Math.floor(i / N)
  for (const [dx, dy] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nx = x + dx, ny = y + dy
    if (nx >= 0 && nx < N && ny >= 0 && ny < N) board[ny * N + nx] = !board[ny * N + nx]
  }
}
function newGame() {
  const board = new Array(N * N).fill(false)
  // Pressed from solved, so it can be solved: as many presses undo it.
  while (!board.some(Boolean)) {
    for (let k = 0; k < 9; k++) flip(board, Math.floor(Math.random() * N * N))
  }
  S.board = board
  S.moves = 0
  save()
}

const Cell = memo(({ i, on, accent }) => (
  <div className={`w-[${cellW}px] h-[${cellW}px] rounded-xl ${on ? `bg-${accent}-400 active:bg-${accent}-600` : 'bg-white/10 active:bg-white/25'}`}
    onClick={() => { flip(S.board, i); S.moves++; save() }} />
))

const Lights = ({ accent }) => {
  const lit = S.board.filter(Boolean).length
  const solved = lit === 0
  return (
    <div className="flex flex-col gap-3 items-center">
      <div className="flex items-center justify-between w-full h-10">
        <div className="flex flex-col">
          <span className="text-lg font-bold">Lights Out</span>
          <span className="text-xs text-slate-400">{`${lit} lit, ${S.moves} moves`}</span>
        </div>
        <div className={`flex items-center h-9 px-4 rounded-full bg-${accent}-600 active:bg-${accent}-800`}
          onClick={() => newGame()}>
          <span className="text-sm font-semibold">New game</span>
        </div>
      </div>
      <div className={`w-[${boardW}px]`}>
        <div className="grid grid-cols-5 gap-[6px]">
          {S.board.map((on, i) => <Cell i={i} on={on} accent={accent} />)}
        </div>
        {solved ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-1 rounded-2xl bg-black/70">
            <span className={`text-3xl font-bold text-${accent}-300`}>Solved!</span>
            <span className="text-sm text-slate-300">{`in ${S.moves} moves`}</span>
          </div>
        ) : null}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- motion

const BALL_COLORS = ['#38bdf8', '#f472b6', '#facc15', '#4ade80', '#a78bfa', '#fb923c']
function newBall(x, y, n) {
  const angle = (n * 2.39996) % (Math.PI * 2)
  const speed = 140 + (n % 3) * 40
  return { x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, t0: Date.now(), r: 14 + (n % 3) * 4, c: n % BALL_COLORS.length }
}
// Where a point moving at `v` px/s from `p` is after `t` s between 0 and `span`.
const bounce = (p, v, t, span) => {
  const d = (((p + v * t) % (2 * span)) + 2 * span) % (2 * span)
  return d > span ? 2 * span - d : d
}
const frames = []

const Motion = ({ accent, now }) => {
  const fps = frames.length
  const spin = ((now % 1200) / 1200) * 360
  const wave = []
  for (let x = 0; x <= pageW; x += 16) {
    wave.push(`${x === 0 ? 'M' : 'L'}${x} ${(motionH - 40 + Math.sin(x / 40 + now / 300) * 14).toFixed(1)}`)
  }
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center justify-between h-8">
        <span className="text-sm text-slate-400">{`${S.balls.length} balls. Tap to add one, hold to reset.`}</span>
        <div className="flex items-center h-7 px-3 rounded-full bg-white/10">
          <span className={`text-sm font-bold text-${accent}-300`}>{`${fps} fps`}</span>
        </div>
      </div>
      <div className={`w-[${pageW}px] h-[${motionH}px] rounded-2xl bg-slate-950 border border-white/10`}
        onPointerDown={(e) => {
          if (S.balls.length < 12) S.balls.push(newBall(Math.round(e.localX), Math.round(e.localY), S.balls.length))
          save()
        }}
        onLongPress={() => set({ balls: [newBall(120, 90, 0)] })}>
        <svg className="w-full h-full" viewBox={`0 0 ${pageW} ${motionH}`}>
          <path d={wave.join(' ')} fill="none" stroke="#334155" strokeWidth={3} strokeLinecap="round" />
          <g transform={`translate(${pageW - 44} 44) rotate(${spin.toFixed(1)})`}>
            <circle cx={0} cy={0} r={22} fill="none" stroke="#1e293b" strokeWidth={6} />
            <path d="M0 -22 A22 22 0 0 1 22 0" fill="none" stroke="#e2e8f0" strokeWidth={6} strokeLinecap="round" />
          </g>
          {S.balls.map((b) => {
            const t = (now - b.t0) / 1000
            const x = b.r + bounce(b.x - b.r, b.vx, t, pageW - 2 * b.r)
            const y = b.r + bounce(b.y - b.r, b.vy, t, motionH - 2 * b.r)
            return <circle cx={x.toFixed(1)} cy={y.toFixed(1)} r={b.r} fill={BALL_COLORS[b.c]} />
          })}
        </svg>
      </div>
    </div>
  )
}

// ----------------------------------------------------------------- touch

const Touch = ({ accent }) => {
  const log = (e) => {
    S.events.push([e.type, Math.round(e.localX), Math.round(e.localY)])
    if (S.events.length > 12) S.events.shift()
    S.counts[e.type] = (S.counts[e.type] ?? 0) + 1
    save()
  }
  const last = S.events[S.events.length - 1]
  return (
    <div className="flex flex-col gap-3">
      <div className={`w-[${pageW}px] h-[${padH}px] rounded-2xl bg-slate-900 border-2 border-white/10 hover:border-${accent}-400`}
        onClick={log} onDoubleClick={log} onLongPress={log} onPointerDown={log} onPointerUp={log} onPointerMove={log}>
        <svg className="w-full h-full" viewBox={`0 0 ${pageW} ${padH}`}>
          {S.events.map(([type, x, y], i) => {
            const fade = (i + 1) / S.events.length
            const r = { tap: 16, doubleTap: 26, longPress: 36, pointerDown: 5, pointerUp: 10, pointerMove: 3 }[type] ?? 8
            const fill = type === 'pointerDown' || type === 'longPress' || type === 'pointerMove'
            return <circle cx={x} cy={y} r={r} fill={fill ? EVENT_COLORS[type] : 'none'}
              fillOpacity={type === 'longPress' ? 0.35 * fade : fade}
              stroke={EVENT_COLORS[type]} strokeWidth={fill ? 0 : 3} strokeOpacity={fade} />
          })}
        </svg>
        <div className="absolute inset-x-0 bottom-2 flex justify-center">
          <span className="text-sm text-slate-400">
            {last ? `${last[0]} at ${last[1]}, ${last[2]}` : 'Tap, hold, drag'}
          </span>
        </div>
      </div>
      <div className="flex gap-2">
        {Object.keys(EVENT_COLORS).map((type) => (
          <div className="flex-1 flex flex-col items-center rounded-xl bg-white/5 py-1">
            <span className={`text-lg font-bold text-[${EVENT_COLORS[type]}]`}>{`${S.counts[type] ?? 0}`}</span>
            <span className="text-xs text-slate-400 truncate">{type}</span>
          </div>
        ))}
      </div>
      <div className="flex gap-2 h-12">
        <div className={`flex-1 flex items-center justify-center rounded-xl bg-white/10 active:bg-${accent}-600`}>
          <span className="text-sm font-semibold">active:</span>
        </div>
        <div className="flex-1 flex items-center justify-center rounded-xl border-2 border-white/10 hover:border-white hover:bg-white/5">
          <span className="text-sm font-semibold">hover:</span>
        </div>
        <div className="group flex-1 flex items-center justify-center gap-2 rounded-xl bg-white/5">
          <div className={`w-3 h-3 rounded-full bg-slate-600 group-hover:bg-${accent}-400`} />
          <span className="text-sm font-semibold text-slate-400 group-hover:text-white">group-hover:</span>
        </div>
      </div>
    </div>
  )
}

// ------------------------------------------------------------------ page

const PAGES = { controls: Controls, paint: Paint, lights: Lights, touch: Touch }
const two = (n) => String(n).padStart(2, '0')

// A page that only changes when the state does (`rev`).
const Page = memo(({ tab, accent, rev }) => {
  const Body = PAGES[tab] ?? Controls
  return <Body accent={accent} />
})

const Title = memo(() => (
  <div className="flex items-center gap-2">
    <Mark />
    <span className="text-lg font-bold">Kitchen sink</span>
  </div>
))

// The size the UI is laid out at: the image it draws into, else the frame
// as the scene sees it (app.frame is the panel's, before the turn).
const uiSize = (app, context) => {
  const turned = [90, 270].includes(app.frame.rotate)
  return [context?.imageWidth ?? (turned ? app.frame.height : app.frame.width),
    context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)]
}

const fit = ([w, h]) => {
  pageW = w - 32; sliderW = pageW - 32; paintH = h - 204; motionH = h - 188; padH = h - 272
  boardW = Math.min(pageW, h - 196); cellW = Math.floor((boardW - 24) / 5) // five cells, four 6 px gaps
  canvasW = pageW - 2 * INSET; canvasH = paintH - 2 * INSET
}

export function get(app, context) {
  fit(uiSize(app, context))
  load()
  if (S.tab === 'paint') {
    // The same canvases every render; made afresh (a new interpreter), they get the record again.
    canvas = frameos.canvas('paint', canvasW, canvasH, PAPER)
    base = frameos.canvas('paint-base', canvasW, canvasH, PAPER)
    if (base?.fresh) for (const stroke of S.strokes.slice(0, S.based)) frameos.draw(base, strokeSvg(stroke))
    if (canvas?.fresh || base?.fresh) redraw()
  }
  // `at` (a field) pins the time, for a snapshot; empty, it is the clock.
  const now = app.config.at ? new Date(app.config.at).getTime() : Date.now()
  frames.push(now)
  while (frames.length && now - frames[0] > 1000) frames.shift()
  // Off the motion page, one render a second, just after it turns.
  if (S.tab !== 'motion') frameos.setNextSleep(1.02 - (now % 1000) / 1000)
  const accent = S.accent
  const d = new Date(now)
  const events = Object.values(S.counts).reduce((a, b) => a + b, 0)
  return (
    <div className="flex flex-col bg-[#0b1020] text-white">
      <div className="flex items-center justify-between h-12 px-4 bg-black/30 border-b border-white/10">
        <Title />
        <span className={`text-lg font-mono text-${accent}-200`}>{`${two(d.getHours())}:${two(d.getMinutes())}:${two(d.getSeconds())}`}</span>
      </div>
      <div className="flex-1 p-4">
        {S.tab === 'motion' ? <Motion accent={accent} now={now} /> : <Page tab={S.tab} accent={accent} rev={S.rev ?? 0} />}
      </div>
      <div className="flex h-16 bg-black/40 border-t border-white/10">
        {TABS.map(([id, label, path]) => (
          <Tab id={id} label={label} d={path} active={S.tab === id} accent={accent} badge={id === 'touch' ? events : 0} />
        ))}
      </div>
    </div>
  )
}
